    """The distinct nonzero colors in the grid."""
    return {v for row in grid for v in row if v}

def color_boxes(grid):
    """Per color (in ascending order), its bounding-box subgrid, from color_boxes_at."""
    return [b for _, b in sorted(color_boxes_at(grid))]

def color_boxes_at(grid):
    """For each color, (top, left, its bounding-box subgrid); colors in ascending order."""
    out = []
    for c in sorted(colors(grid)):
        cells = [(i, j) for i, row in enumerate(grid) for j, v in enumerate(row) if v == c]
        top = min(i for i, j in cells); left = min(j for i, j in cells)
        h = max(i for i, j in cells) - top + 1
        w = max(j for i, j in cells) - left + 1
        out.append((top, left, [[grid[top + i][left + j] for j in range(w)] for i in range(h)]))
    return out

def hstack(grids):
    """Grids side by side, left to right, padded to a common height."""
    h = max(len(g) for g in grids)
    padded = [g + [[0] * len(g[0]) for _ in range(h - len(g))] for g in grids]
    return [[v for g in padded for v in row] for row in zip(*padded)]

def vstack(grids):
    """Grids stacked top to bottom, padded to a common width."""
    w = max(len(g[0]) for g in grids)
    return [row + [0] * (w - len(row)) for g in grids for row in g]

def arrange_shapes(grid):
    """Each color's bounding-box shape, laid out horizontally ordered left to right if the
    shapes' row ranges overlap, otherwise vertically ordered top to bottom."""
    boxes = color_boxes_at(grid)
    rows = [(t, t + len(b) - 1) for t, l, b in boxes]
